'use strict';
// Local simulation only. No real inventory API credentials or requests.
const stockChannels=['Shopee','Lazada','TikTok Shop'];let blockedChannel='';let stockRevision=1;let stockEvents=[];
const centralSnapshot=()=>Object.fromEntries(PRODUCTS.map(p=>[p.sku,available(p.sku)]));let lastStock=centralSnapshot();
const publishedStock=Object.fromEntries(stockChannels.map(c=>[c,{qty:{...lastStock},revision:stockRevision,state:'สาธิต: ส่งค่าแล้ว'}]));
function publishStock(reason){let now=centralSnapshot();if(JSON.stringify(now)===JSON.stringify(lastStock))return;stockRevision++;lastStock={...now};for(let ch of stockChannels){let t=publishedStock[ch];if(ch===blockedChannel){t.state='สาธิต: รอลองใหม่'}else{t.qty={...now};t.revision=stockRevision;t.state='สาธิต: ส่งค่าแล้ว'}stockEvents.unshift({channel:ch,revision:stockRevision,reason,status:t.state,time:new Date().toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',second:'2-digit'})})}}
function retryStock(){blockedChannel='';for(let ch of stockChannels){let t=publishedStock[ch];t.qty={...lastStock};t.revision=stockRevision;t.state='สาธิต: ส่งค่าแล้ว'}stockEvents.unshift({channel:'ทุกช่องทาง',revision:stockRevision,reason:'ส่งยอดล่าสุดอีกครั้ง ไม่ย้อนใช้ยอดเก่า',status:'สาธิต: ส่งค่าแล้ว',time:new Date().toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',second:'2-digit'})});shell();toast('จำลองส่งยอดกลางล่าสุดครบ 3 ช่องทางแล้ว')}
const baseLog=log;log=function(o,text){baseLog(o,text);publishStock(text)};
function stockSyncPanel(){let pending=stockChannels.filter(ch=>publishedStock[ch].revision!==stockRevision);return `<div style="margin:22px 0">${panel('สต๊อกกลาง → ทุกช่องทางขาย','ทุกช่องทางอ้างอิงสินค้ากองเดียวกัน จำนวนที่แสดงแต่ละช่องทางห้ามนำมาบวกกัน',`<div class="panel-body"><div class="stock-hub"><div><span class="eyebrow">ONE SHARED INVENTORY</span><strong>${num(sum(PRODUCTS,p=>available(p.sku)))} <small>ชิ้นพร้อมขาย</small></strong><p>คงคลัง − กันไว้ = พร้อมขาย</p><span class="badge">เวอร์ชัน ${stockRevision} · ข้อมูลสาธิต</span></div><div class="stock-destinations">${stockChannels.map(ch=>{let p=publishedStock[ch],stale=p.revision!==stockRevision;return `<div class="stock-destination ${stale?'stale':''}">${channelLogo(ch)}<span>${ch}<small>${p.state} · v${p.revision}</small></span>${icon(stale?'alert':'check')}</div>`}).join('')}</div></div><div class="notice ${pending.length?'':'blue'}">${icon(pending.length?'alert':'sync')}${pending.length?'Lazada ยังไม่รับยอดล่าสุดในสถานการณ์จำลอง กดส่งใหม่เพื่อให้ยอดตรงกัน':'การกันสินค้า ยกเลิก และรับสินค้าเข้า จะส่งยอดพร้อมขายใหม่อัตโนมัติในแบบจำลอง'}${blockedChannel&&!pending.length?' · กำลังจำลอง Lazada ไม่พร้อมรับ รอการเปลี่ยนสต๊อกครั้งถัดไป':''}</div><div class="table-scroll"><table class="data-table"><thead><tr><th>SKU</th><th class="num">พร้อมขายกลาง</th>${stockChannels.map(ch=>`<th class="num">${ch}</th>`).join('')}</tr></thead><tbody>${PRODUCTS.map(p=>`<tr><td>${p.sku}</td><td class="num"><b>${available(p.sku)}</b></td>${stockChannels.map(ch=>`<td class="num ${publishedStock[ch].qty[p.sku]!==available(p.sku)?'negative':'positive'}">${publishedStock[ch].qty[p.sku]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="actions" style="margin-top:18px">${button('ส่งยอดล่าสุดใหม่ (สาธิต)','retry-stock','sync','primary')}${button(blockedChannel?'กำลังจำลองช่องทางขัดข้อง':'จำลอง Lazada ซิงค์ไม่สำเร็จ','fail-stock','alert')}</div><p class="section-sub">Facebook, LINE OA, Review และ Offline sales ใช้ยอดกลางนี้โดยตรง ส่วนตัวเลข Shopee / Lazada / TikTok ด้านบนเป็นผลตอบรับจำลอง ยังไม่ได้เขียนสต๊อกไปแพลตฟอร์มจริง</p></div>`)}</div>`}
const inventoryBase=views.inventory;views.inventory=()=>inventoryBase()+stockSyncPanel()+panel('ประวัติส่งยอดสต๊อกสาธิต','ส่งเฉพาะยอดพร้อมขายล่าสุด และลองใหม่เมื่อช่องทางไม่พร้อม',`<div class="table-scroll"><table class="data-table"><thead><tr><th>เวลา</th><th>ช่องทาง</th><th>เวอร์ชัน</th><th>เหตุการณ์</th><th>ผลจำลอง</th></tr></thead><tbody>${stockEvents.slice(0,12).map(e=>`<tr><td>${e.time}</td><td>${e.channel}</td><td>v${e.revision}</td><td>${esc(e.reason)}</td><td>${e.status}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">ลองกันสินค้า ยกเลิก หรือรับสินค้าเข้า แล้วดูประวัติการส่งยอด</td></tr>'}</tbody></table></div>`);
const originalOverview=overview;overview=function(){let html=originalOverview(),reviews=filtered().filter(o=>o.channel==='Review'&&o.status!=='cancelled');return html+panel('สินค้า Review / ส่งฟรีให้ผู้รีวิว','ใช้สต๊อกเดียวกันกับยอดขาย แต่ไม่นับเป็นรายได้',`<div class="panel-body"><div class="stat-line"><span>ออเดอร์ส่งรีวิว</span><strong>${reviews.length} ออเดอร์</strong></div><div class="stat-line"><span>จำนวนสินค้าแจก</span><strong>${sum(reviews,o=>sum(o.items,l=>l.qty))} ชิ้น</strong></div><div class="stat-line"><span>ต้นทุนสินค้าที่ส่งมอบแล้ว</span><strong>${money(sum(reviews.filter(o=>['shipped','delivered'].includes(o.status)),o=>sum(o.items,l=>l.qty*l.cost)))}</strong></div></div>`)};
const originalExtraAction=extraAction;extraAction=function(a){if(a==='retry-stock'){retryStock();return}if(a==='fail-stock'){blockedChannel='Lazada';shell();toast('จำลอง Lazada ไม่พร้อมรับ ลองรับสินค้าเข้าหรือกันสต๊อก แล้วกลับมาดูยอด');return}originalExtraAction(a)};
const baseBlueprint=views.blueprint;views.blueprint=()=>`<div class="notice blue">${icon('box')}ยืนยันขอบเขต: สต๊อกกลางชุดเดียวสำหรับทุกช่องทาง รวมการส่ง Review ฟรี และส่งยอดพร้อมขายไปอัปเดต ecommerce</div>${panel('กติกาสต๊อกกลางในระบบจริง','คลังเป็นแหล่งยอดหลัก ทุกแพลตฟอร์มรับยอดพร้อมขายจากที่เดียว',`<div class="panel-body"><div class="definition-grid"><div class="definition"><strong>กันสินค้าเมื่อยืนยันรับออเดอร์</strong>ออเดอร์ทุกแหล่งใช้ธุรกรรมเดียวกัน การส่งสินค้า Review ต้องกันและตัดเหมือนการขาย ไม่กันซ้ำเมื่อ Webhook เดิมเข้ามาอีก</div><div class="definition"><strong>ส่งยอดใหม่เมื่อมีการเปลี่ยนแปลง</strong>ใช้คิวส่งสต๊อก ตรวจเวอร์ชัน จัดการ rate limit และลองใหม่ พร้อมตรวจยอดบนแพลตฟอร์มเป็นระยะ</div><div class="definition"><strong>ลดโอกาสขายเกินด้วยจำนวนสำรอง</strong>การอัปเดตข้ามระบบมีความหน่วง ต้องกำหนด safety stock และกติกาพักขายเมื่อช่องทางซิงค์ค้าง ไม่รับประกันว่า oversell เป็นศูนย์</div><div class="definition"><strong>คืนสินค้าไม่เท่ากับคืนเงิน</strong>ยกเลิกก่อนส่งปล่อยยอดกันครั้งเดียว คืนเงินหลังส่งไม่เพิ่มสต๊อก ต้องตรวจรับสินค้าจริงก่อนนำกลับมาขาย</div></div></div>`)}<div style="height:20px"></div>`+baseBlueprint();
